import{_ as s,a0 as l,w as p,s as d,I as t,x as r,a1 as n,A as i,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"一起來看看 Windows Nano Server 2016 | LCTT x X-CMD","titleTemplate":false,"description":"一起來看看 Windows Nano Server 2016 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一起來看看 Windows Nano Server 2016 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一起來看看 Windows Nano Server 2016 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20160914 Down and dirty with Windows Nano Server 2016","title":"一起來看看 Windows Nano Server 2016","tag":"201611","desc":""},"relativePath":"201611/20160914 Down and dirty with Windows Nano Server 2016.md","filePath":"[post].md"}'),m={name:"201611/20160914 Down and dirty with Windows Nano Server 2016.md"};function w(g,e,v,N,S,u){const o=l("Link");return p(),d("div",null,[e[22]||(e[22]=t("h1",{id:"一起來看看-windows-nano-server-2016",tabindex:"-1"},[r("一起來看看 Windows Nano Server 2016 "),t("a",{class:"header-anchor",href:"#一起來看看-windows-nano-server-2016","aria-label":"Permalink to “一起來看看 Windows Nano Server 2016”"},"​")],-1)),e[23]||(e[23]=t("p",null,[t("img",{src:"http://images.techhive.com/images/article/2016/04/pokes-fun-at-1164459_1280-100654917-primary.idge.jpg",alt:""})],-1)),e[24]||(e[24]=t("blockquote",null,[t("p",null,"對於遠程 Windows 服務器管理，Nano Server 是快速的功能強大的工具，但是你需要知道你在做的是什麼。")],-1)),t("p",null,[e[1]||(e[1]=r("下面談論",-1)),n(o,{href:"http://www.infoworld.com/article/3049191/windows-server/nano-server-a-slimmer-slicker-windows-server-core.html"},{default:i(()=>[...e[0]||(e[0]=[r("即將到來的 Windows Server 2016 的 Nano 版本",-1)])]),_:1}),e[2]||(e[2]=r("，帶遠程管理和命令列設計，考慮到了私有云和數據中心。但是，談論它和動手用它區別還是很大的，讓我們深入看下去。",-1))]),e[25]||(e[25]=t("p",null,"沒有本地登錄，且所有的程序、工具和代理都是 64 位，安裝升級快捷，只需要非常少的時間就能重啓。它非常適合做計算節點（無論在不在集羣）、存儲主機、DNS 服務器、IIS web 服務器，以及在容器中提供主機服務或者虛擬化的客户操作系統。",-1)),e[26]||(e[26]=t("p",null,"Nano 服務器也並不是太好玩的，你必須知道你要完成什麼。你會看着遠程的 PowerShell 的連接而不知所措，但如果你知道你要做什麼的話，那它就非常方便和強大。",-1)),t("p",null,[e[4]||(e[4]=r("微軟為設置 Nano 服務器提供了一個",-1)),n(o,{href:"https://technet.microsoft.com/en-us/windows-server-docs/compute/nano-server/getting-started-with-nano-server"},{default:i(()=>[...e[3]||(e[3]=[r("快速入門手冊",-1)])]),_:1}),e[5]||(e[5]=r(" ，在這我給大傢俱體展示一下。",-1))]),e[27]||(e[27]=a('<p>首先，你必須創建一個 .vhd 格式的虛擬磁盤文件。在步驟一中，我有幾個文件不在正確的位置的小問題，Powershell 總是提示不匹配，所以我不得不反覆查找文件的位置方便我可以用 ISO 信息（需要把它拷貝粘貼到你要創建 .vhd 文件的服務器上）。當你所有的東西都位置正確了，你可以開始創建 .vhd 文件的步驟了。</p><p><img src="http://images.techhive.com/images/article/2016/09/nano-server-1-100682371-large.idge.jpg" alt=""></p><p><em>步驟一：嘗試運行 New-NanoServerImage 腳本時，很多文件路徑錯誤，我把文件位置的問題搞定後，就能進行下去創建 .vhd 文件了（如圖所示）</em></p><p>接下來，你可以用創建 VM 嚮導在 Hyper-V 裏面創建 VM 虛擬機，你需要指定一個存在的虛擬磁盤同時指向你新創建的 .vhd 文件。（步驟二）</p><p><img src="http://images.techhive.com/images/article/2016/09/nano-server-2-100682368-large.idge.jpg" alt=""></p><p><em>步驟二：連接虛擬磁盤（一開始創建的）</em></p><p>當你啓動 Nano 服務器的時候，你或許會發現有內存錯誤，提示你已經分配了多少內存，如果你還有其他 VM 虛擬機的話， Hyper-V 服務器剩餘了多少內存。我已經關閉了一些虛機以增加可用內存，因為微軟説 Nano 服務器最少需要 512M 內存，但是它又推薦你至少 800M，最後我分配了 8G 內存因為我給它 1G 的時候根本不能用，為了方便，我也沒有嘗試其他的內存配置。</p><p>最後我終於到達登錄界面，到達 Nano Server Recovery Console 界面（步驟三），Nano 服務器的基本命令界面。</p><p><img src="http://images.techhive.com/images/article/2016/09/nano-server-3-100682369-large.idge.jpg" alt=""></p><p><em>步驟三：Nano 服務器的恢復窗口</em></p><p>本來我以為進到這裏會很美好，但是當我弄明白幾個細節（如何加入域，彈出個磁盤，添加用户），我明白一些配置的細節，用幾個參數運行 New-NanoServerImage cmdlet 會變得很簡單。</p><p>然而，當你的服務器運行時，也有辦法確認它的狀態，就像步驟四所示，這一切都始於一個遠程 PowerShell 連接。</p><p><img src="http://images.techhive.com/images/article/2016/09/nano-server-4-100682370-large.idge.jpg" alt=""></p><p><em>步驟四：從 Nano 服務器恢復窗口得到的信息，你可以從遠程運行一個 Powershell 連接。</em></p>',14)),t("p",null,[e[7]||(e[7]=r("微軟展示瞭如何創建連接，但是嘗試了四個不同的方法，我發現 ",-1)),n(o,{href:"https://msdn.microsoft.com/en-us/library/mt708805(v=vs.85).aspx"},{default:i(()=>[...e[6]||(e[6]=[r("MSDN",-1)])]),_:1}),e[8]||(e[8]=r(" 提供的是最好的方式，步驟五展示。",-1))]),e[28]||(e[28]=a('<p><img src="http://images.techhive.com/images/article/2016/09/nano-server-5-100682372-large.idge.jpg" alt=""></p><p><em>步驟五：創建到 Nano 服務器的 PowerShell 遠程連接</em></p><p>提示：創建遠程連接，你可以用下面這條命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Enter-PSSession –ComputerName &quot;192.168.0.100&quot;-Credential ~\\Administrator.</span></span></code></pre></div><p>如果你提前知道這台服務器將要做 DNS 服務器或者集羣中的一個計算節點，可以事先在 .vhd 文件中加入一些角色和特定的軟件包。如果不太清楚，你可以先建立 PowerShell 連接，然後安裝 NanoServerPackage 並導入它，你就可以用 Find-NanoServerPackage 命令來查找你要部署的軟件包了（步驟六）。</p><p><img src="http://images.techhive.com/images/article/2016/09/nano-server-6-100682373-large.idge.jpg" alt=""></p><p><em>步驟六：你安裝完並導入 NanoServerPackage 後，你可以找到你需要啓動服務器的工具以及設置的用户和你需要的一些其他功能包。</em></p><p>我測試了安裝 DNS 安裝包，用 <code>Install-NanoServerPackage –Name Microsoft-NanoServer-DNS-Package</code> 這個命令。安裝好後，我用 <code>Enable-WindowsOptionalFeature –Online –FeatureName DNS-Server-Full-Role</code> 命令啓用它。</p><p>之前我並不知道這些命令，之前也從來沒運行過，也沒有弄過 DNS，但是現在稍微研究一下我就能用 Nano 服務器建立一個 DNS 服務並且運行它。</p><p>接下來是用 PowerShell 來配置 DNS 服務器。這個複雜一些，需要網上研究一下。但是它也不是那麼複雜，當你學習了使用 cmdlet ，就可以用 <code>Add-DNSServerPrimaryZone</code> 添加 zone，用 <code>Add-DNSServerResourceRecordA</code> 命令在 zone 中添加記錄。</p><p>做完這些命令列的工作，你可能需要驗證是否起效。你可以快速瀏覽一下 PowerShell 命令，沒有太多的 DNS 命令（使用 <code>Get-Command</code> 命令）。</p><p>如果你需要一個圖形化的配置，你可以從一個圖形化的主機上用圖形管理器打開 Nano 服務器的 IP 地址。右擊需要管理的服務器，提供你的驗證信息，你連接好後，在圖形管理器中右擊然後選擇 Add Roles and Features，它會顯示你安裝好的 DNS 服務，如步驟七所示。</p><p><img src="http://images.techhive.com/images/article/2016/09/nano-server-7-100682374-large.idge.jpg" alt=""></p><p><em>步驟七：通過圖形化界面驗證 DNS 已經安裝</em></p><p>不用麻煩登錄服務器的遠程桌面，你可以用服務器管理工具來進行操作。當然你能驗證 DNS 角色不代表你能夠通過 GUI 添加新的角色和特性，它有命令列就足夠了。你現在可以用 Nano 服務器做一些需要的調整了。</p><hr>',16)),t("p",null,[e[10]||(e[10]=r("via: ",-1)),n(o,{href:"http://www.infoworld.com/article/3119770/windows-server/down-and-dirty-with-windows-nano-server-2016.html"},{default:i(()=>[...e[9]||(e[9]=[r("http://www.infoworld.com/article/3119770/windows-server/down-and-dirty-with-windows-nano-server-2016.html",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=r("作者：",-1)),n(o,{href:"http://www.infoworld.com/author/J.-Peter-Bruzzese/"},{default:i(()=>[...e[11]||(e[11]=[r("J. Peter Bruzzese",-1)])]),_:1}),e[15]||(e[15]=r(" 譯者：",-1)),n(o,{href:"https://github.com/jiajia9linuxer"},{default:i(()=>[...e[12]||(e[12]=[r("jiajia9linuxer",-1)])]),_:1}),e[16]||(e[16]=r(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...e[13]||(e[13]=[r("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=r("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[17]||(e[17]=[r("LCTT",-1)])]),_:1}),e[20]||(e[20]=r(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:i(()=>[...e[18]||(e[18]=[r("Linux中國",-1)])]),_:1}),e[21]||(e[21]=r(" 榮譽推出",-1))])])}const D=s(m,[["render",w]]);export{T as __pageData,D as default};
